    status: "active",
  },
  {
    id: "u-3",
    name: "Grace Hopper",
    email: "grace@example.com",
    status: "paused",
  },
  {
    id: "u-4",
    name: "Katherine Johnson",
    email: "katherine@example.com",
    status: "active",
  },
  {
    id: "u-5",
    name: "Linus Torvalds",
    email: "linus@example.com",
    status: "active",
  },
  {
    id: "u-6",
