import from "react" { useEffect }

obj StorageEvent {
    has key: str | None = None;
    has newValue: str | None = None;
}

def read_storage[T](key: str, initial_value: T) -> T {
    if not window {
        return initial_value;
    }
    try {
        item = localStorage.getItem(key);
        if item {
            return JSON.parse(item) as T;
        }
        return initial_value;
    } except Exception as e {
        console.warn(f"Error reading localStorage key \"{key}\": {str(e)}");
        return initial_value;
    }
}

def:pub useLocalStorage[T](key: str, initial_value: T) -> list[object] {
    has stored_value: T = read_storage(key, initial_value);

    def set_value(value: T | Callable[[T], T]) {
        try {
            value_to_store = value(stored_value) if callable(value) else value;
            stored_value = value_to_store;
            if window {
                localStorage.setItem(key, JSON.stringify(value_to_store));
            }
        } except Exception as e {
            console.warn(f"Error setting localStorage key \"{key}\": {str(e)}");
        }
    }

    useEffect(lambda {
        handle_storage_change = lambda (event: StorageEvent) {
            if event.key == key and event.newValue {
                stored_value = JSON.parse(event.newValue) as T;
            }
        };
        window.addEventListener("storage", handle_storage_change);
        return lambda {
            window.removeEventListener("storage", handle_storage_change);
        };
    }, [key]);

    return [stored_value, set_value];
}

