glob BASE_DELAY_MS = 500;

async def fetchWithRetry(url: str | object, requestInit: dict[str, object] | None = None) -> object {
    lastError: BaseException | None = None;
    for attempt in range(MAX_RETRIES + 1) {
        try {
            return await fetch(url, requestInit);
        } except BaseException as err {
            lastError = err;
            if attempt < MAX_RETRIES {
                await asyncio.sleep((BASE_DELAY_MS * (2 ** attempt)) / 1000.0);
            }
        }
    }
    if lastError is not None {
        raise lastError;
    }
    raise RuntimeError("fetchWithRetry failed");
}
