        details: `align-self is "${alignSelf}" but parent display is "${ctx.parentDisplay}". align-self works on flex/grid items only.`,
        suggestion:
          'Set display: flex or display: grid on the parent element, or remove align-self.',
      }),
    ];
  },
};

registerRule(rule);

