import re;
import math;

glob:pub COACH_TTS_MAX_CHARS = 360;

def:pub sanitizeTtsText(text: str) -> str {
    cleaned: str = text.strip().replace("\u00a0", " ");
    cleaned = re.sub(r"[\u201c\u201d]", "\"", cleaned);
    cleaned = re.sub(r"[\u2018\u2019]", "'", cleaned);
    cleaned = re.sub(r"\s+", " ", cleaned);
    return cleaned;
}

def:pub truncateForCoachTts(text: str, maxChars: int = COACH_TTS_MAX_CHARS) -> str {
    sanitized = sanitizeTtsText(text);
    if len(sanitized) <= maxChars {
        return sanitized;
    }
    slice = sanitized[0:maxChars];
    boundaries = [slice.rfind("。"), slice.rfind("！"), slice.rfind("？"), slice.rfind("."), slice.rfind("!"), slice.rfind("?")];
    last = max(boundaries);
    if last >= int(maxChars * 0.45) {
        return slice[0:last + 1].strip();
    }
    return slice.strip();
}

def:pub prepareCoachTtsText(text: str) -> str {
    return truncateForCoachTts(sanitizeTtsText(text));
}

def:pub splitCoachTtsSegments(text: str, maxSegments: int = 6) -> list[str] {
    sanitized = sanitizeTtsText(text);
    if not sanitized {
        return [];
    }
    parts = [part.strip() for part in re.split(r"(?<=[。！？.!?])\s+", sanitized) if part.strip()];
    if len(parts) <= maxSegments {
        return parts;
    }
    chunkSize = max(1, math.ceil(len(parts) / maxSegments));
    segments: list[str] = [];
    for i in range(0, len(parts), chunkSize) {
        segment = " ".join(parts[i:i + chunkSize]).strip();
        if segment {
            segments.append(segment);
        }
        if len(segments) >= maxSegments {
            break;
        }
    }
    return segments;
}

