type TranslateFn = (key: string) => string;

/**
 * Create 2FA enable schema with translated messages
 */
export function createTwoFactorEnableSchema(t: TranslateFn) {
    return z.object({
        password: z.string().min(1, t("validation.password.required")),
    });
}

