interface MultiStateSendButtonProps extends Omit<
  HTMLMotionProps<"button">,
  "children" | "onAnimationStart"
> {
  idleLabel?: string;
  loadingLabel?: string;
  successLabel?: string;
  sendDuration?: number;
  autoResetDelay?: number;
  onSend?: () => void;
}

const MultiStateSendButton = React.forwardRef<
  HTMLButtonElement,
  MultiStateSendButtonProps
>(
  (
    {
      idleLabel = "Send Message",
      loadingLabel = "Sending...",
      successLabel = "Sent Successfully!",
      sendDuration = 1800,
      autoResetDelay = 3000,
      onSend,
      className,
      onClick,
      disabled,
      ...props
    },
    ref,
  ) => {
    const [status, setStatus] = React.useState<"idle" | "loading" | "success">(
      "idle",
    );

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (status !== "idle") return;

      setStatus("loading");

      setTimeout(() => {
        setStatus("success");
        if (onSend) onSend();

        if (autoResetDelay > 0) {
          setTimeout(() => {
            setStatus("idle");
          }, autoResetDelay);
        }
      }, sendDuration);

      if (onClick) onClick(e);
    };

    return (
      <motion.button
        ref={ref}
        onClick={handleClick}
        disabled={disabled || status !== "idle"}
        whileHover={{ scale: status === "idle" ? 1.02 : 1 }}
        whileTap={{ scale: status === "idle" ? 0.97 : 1 }}
