def:pub decodeExperienceVariantsMap(encodedExperienceVariantsMap: str) -> dict[str, int] {
    experientVariantsAssignments = encodedExperienceVariantsMap.split(",");
    experienceVariantsMap: dict[str, int] = {};
    for experienceVariantAssignment in experientVariantsAssignments {
        parts: list[str] = experienceVariantAssignment.split("=");
        experienceId = parts[0];
        variantIndexString = parts[1];
        variantIndex = int(variantIndexString);
        if (not experienceId or not variantIndex) {
            continue;
        }
        experienceVariantsMap[experienceId] = variantIndex;
    }
    return experienceVariantsMap;
}

