import from "zod" { EnumLike, z }
import from "@/types/FormFieldsArray" { FormFieldsArray, GenericFieldOptions }
import from "@/types/UtilityTypes" { FieldValueToOptions, MappedFieldOptions }
import from "@/utils/fieldHandlers" { handleNativeZodEnum, handleZodBoolean, handleZodEnum, handleZodNumber, handleZodString }
import from "@/utils/formHelpers" { setDefaultOptions }
import from "@/utils/typeGuards/zodTypeGuards" { isZodBoolean, isZodEnum, isZodNativeEnum, isZodNumber, isZodString }
import from "@/utils/zodHelpers" { unwrapZodType }

def:pub handleFieldValue(fieldKey: str, fieldValue: object, fieldOptions: GenericFieldOptions | None = None) -> GenericFieldOptions {
    defaultOptions = setDefaultOptions(fieldKey, fieldValue);
    mergedOptions = fieldOptions if fieldOptions is not None else {};
    options = {**defaultOptions, **mergedOptions};
    baseType = unwrapZodType(fieldValue);
    if isZodString(baseType) {
        return handleZodString(options);
    }
    elif isZodNumber(baseType) {
        return handleZodNumber(options);
    }
    elif isZodBoolean(baseType) {
        return handleZodBoolean(options);
    }
    elif isZodEnum(baseType) {
        return handleZodEnum(options, fieldValue);
    }
    elif isZodNativeEnum(baseType) {
        return handleNativeZodEnum(options, fieldValue);
    }
    else {
        raise ValueError("Unsupported Zod type");
    }
}

def:pub createOptions(initialSchema: object) -> dict[str, object] {
    options: dict[str, object] = {};
    def withFieldOptions(fieldOptions: dict[str, object]) -> dict[str, object] {
        options = {**options, **fieldOptions};
        return {"withFieldOptions": withFieldOptions, "build": build};
    }
    def build() -> dict[str, object] {
        return options;
    }
    return {"withFieldOptions": withFieldOptions, "build": build};
}

