def:pub resolveRoleMatch(requestedRole: str, knownForDepartment: str) -> str {
    if (requestedRole == "any") {
        return "neutral";
    }
    normalizedDepartment = (knownForDepartment or "").lower();
    if not normalizedDepartment {
        return "neutral";
    }
    if (requestedRole == "director") {
        return ("match" if ("direct" in normalizedDepartment) else "mismatch");
    }
    if ((requestedRole == "actor") or (requestedRole == "actress")) {
        return ("match" if (("acting" in normalizedDepartment) or ("actor" in normalizedDepartment)) else "mismatch");
    }
    return "neutral";
}

