import from "classnames" { default as classnames }
import from "react" { Children, cloneElement, isValidElement }

glob prefixCls = "fam-tabbar";

def:pub TabBar(
    className: str | None = None,
    style: dict[str, object] | None = None,
    selectedColor: str | None = None,
    onClick: Callable[[str], None] | None = None,
    activeKey: str | None = None,
    barBgColor: str | None = None,
    children: object = None,
) -> JsxElement {
    has localActiveKey: str | None = activeKey;

    can with [activeKey] entry {
        localActiveKey = activeKey;
    }

    def handleActiveKeyChange(k: str) {
        localActiveKey = k;
        if onClick {
            onClick(k);
        }
    }

    def renderChildren() -> list[object] {
        mapped = Children.map(children, lambda (child: object) -> object {
            if isValidElement(child) {
                childKey = getattr(child, "key", None);
                return cloneElement(child, {
                    "onClick": handleActiveKeyChange,
                    "fkey": childKey,
                    "selectedColor": selectedColor,
                    "activeKey": localActiveKey,
                });
            }
            return child;
        });
        return mapped if mapped is not None else [];
    }

    wrapCls = classnames(prefixCls, className);
    newStyle = {**style} if style else {};
    if barBgColor {
        newStyle = {**newStyle, "background": barBgColor};
    }

    return <div className={wrapCls} style={newStyle}>{renderChildren()}</div>;
}

