          </div>
        )
      }
      {
        message && (
          <div className={`${prefixCls}-message`}>
            { message }
          </div>
        )
      }
      {/* 扩展节点 */
        expandNode && (
          <div className={`${prefixCls}-expand`}>
            { expandNode }
          </div>
        )
      }

    </div>
  )
}

export default Result;
