import { useState, useLayoutEffect } from 'react';

interface IDimensions {
  width: number;
  height: number;
}

const getWindowDimensions = (): IDimensions => {
  const { innerWidth: width, innerHeight: height } = window;

  return {
    width,
    height,
  };
};

const useWindowDimensions = (): IDimensions => {
  const [windowDimensions, setWindowDimensions] = useState<IDimensions>(getWindowDimensions());

  useLayoutEffect(() => {
    /**
     * Handles the window resize event by updating the state with the new window dimensions.
     */
    const handleResize = (): void => {
      setWindowDimensions(getWindowDimensions());
    };

    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return windowDimensions;
};

export default useWindowDimensions;
```

import from "react" { useState, useEffect }

def getWindowDimensions() -> dict[str, float] {
    return {"width": window.innerWidth as float, "height": window.innerHeight as float};
}

def:pub useWindowDimensions() -> dict[str, float] {
    _state = useState(getWindowDimensions());
    windowDimensions: dict[str, float] = _state[0] as dict[str, float];
    setWindowDimensions = _state[1];
    useEffect(lambda {
        def handle_resize() {
            setWindowDimensions(getWindowDimensions());
        }
        window.addEventListener("resize", handle_resize);
        return lambda {
            window.removeEventListener("resize", handle_resize);
        };
    }, []);
    return windowDimensions;
}

