import re;

def dedupeParagraphs(text: str) -> str {
    paragraphs = [p.strip() for p in re.split(r"\n\n+", text) if p.strip()];
    if len(paragraphs) < 2 {
        return "\n\n".join(paragraphs);
    }
    first = paragraphs[0];
    second = paragraphs[1];
    if second.startswith(first) {
        second = second[len(first):].strip();
    } else {
        for len_val in range(min(len(first), len(second)), 9, -1) {
            if second.startswith(first[:len_val]) {
                second = re.sub(r"^[\s，。、；：！？]+", "", second[len_val:]).strip();
                break;
            }
        }
        firstSentenceMatch = re.match(r"^[^。！？.!?]+[。！？.!?]?", first);
        if firstSentenceMatch {
            opener = re.sub(r"[。！？.!?]$", "", firstSentenceMatch.group(0)).strip();
            if len(opener) >= 6 and second.startswith(opener) {
                second = re.sub(r"^[\s，。、；：！？.!?]+", "", second[len(opener):]).strip();
            }
        }
    }
    if not second {
        return "\n\n".join([first] + paragraphs[2:]);
    }
    return "\n\n".join([first, second] + paragraphs[2:]);
}

def:pub stripVerifyMarkers(text: str) -> str {
    cleaned = re.sub(r"(?i)\s*\[\s*VERIFY:\s*[^\]]+\]", "", text);
    cleaned = re.sub(r"[ \t]+\n", "\n", cleaned);
    return re.sub(r"\n{3,}", "\n\n", cleaned);
}

def:pub stripVerifyBlocks(text: str) -> str {
    return dedupeParagraphs(stripVerifyMarkers(text).strip()).strip();
}

