def stripMarkupForSsr(html: str) -> str {
    text = "";
    insideTag = False;
    for character in html {
        if character == "<" {
            insideTag = True;
            continue;
        }
        if character == ">" {
            insideTag = False;
            continue;
        }
        if not insideTag {
            text += character;
        }
