            }
        } except Exception as e {
            print(f"Error fetching code for {hookName}: {str(e)}");
            code = "// Error loading component code";
            msg = str(e);
            error = msg if msg else "Failed to fetch component code";
        } finally {
            is_loading = False;
        }
    }

