def:pub PromptSuggestionVariants() -> JsxElement {
    has inputValue: str = "";
    has activeCategory: str = "";

    def handleSend() {
        if inputValue.strip() {
            console.log("Sending:", inputValue);
            inputValue = "";
            activeCategory = "";
        }
    }

    def handleKeyDown(e: KeyboardEvent) {
        if e.key == "Enter" and not e.shiftKey {
            e.preventDefault();
            handleSend();
        }
    }

    def handlePromptInputValueChange(value: str) {
        inputValue = value;
        if value.strip() == "" {
            activeCategory = "";
        }
    }

    def selectCategory(label: str) {
        activeCategory = label;
    }

    def selectPrompt(prompt: str) {
        inputValue = prompt;
    }

    activeCategoryData: dict[str, str | list[str]] | None = None;
    for group in suggestionGroups {
        if (group["label"] as str) == activeCategory {
            activeCategoryData = group;
            break;
        }
    }
    showCategorySuggestions = activeCategory != "";

    return <div className="flex w-full flex-col space-y-4">
        <PromptInput
            className="border-input bg-background border shadow-xs"
            value={inputValue}
            onValueChange={handlePromptInputValueChange}
            onKeyDown={handleKeyDown}
            onSubmit={handleSend}
        >
            <PromptInputTextarea placeholder="Type a message or click a suggestion..." />
            <PromptInputActions className="justify-end">
                <Button
