                    <ArrowUpIcon className="h-4 w-4" />
                </Button>
            </PromptInputActions>
        </PromptInput>
        <div className="flex flex-wrap gap-2">
            {[<PromptSuggestion key={group["label"] as str} onClick={lambda { selectCategory(group["label"] as str); }}>
                <BrainIcon className="mr-1 h-4 w-4" />
                {group["label"] as str}
            </PromptSuggestion> for group in suggestionGroups]}
        </div>
        {if showCategorySuggestions and activeCategoryData {
            <div className="flex flex-wrap gap-2">
                {[<PromptSuggestion
                    key={item}
                    highlight={activeCategoryData["highlight"] as str}
                    onClick={lambda { selectPrompt(item); }}
                >
                    {item}
                </PromptSuggestion> for item in (activeCategoryData["items"] as list[str])]}
            </div>
        }}
    </div>;
