        LabelEntry(value="enhancement", label="Enhancement", color="bg-purple-500"),
        LabelEntry(value="documentation", label="Documentation", color="bg-yellow-500"),
        LabelEntry(value="design", label="Design", color="bg-pink-500"),
    ];
    has value: str = "";
    has mounted: bool = False;
    has color_index: int = 0;
    field_id = useId();
    selected = find_label(labels, value);
    trimmed = query.strip();
    exact_match = False;
    for `entry in labels {
        if `entry.label.lower() == trimmed.lower() {
            exact_match = True;
            break;
        }
    }
    show_create = len(trimmed) > 0 and not exact_match;

    useEffect(lambda {
        if open {
            timer = setTimeout(lambda { mounted = True; }, 50);
            return lambda { clearTimeout(timer); };
        }
        mounted = False;
        return lambda { };
    }, [open]);

    def handle_open_change(next_open: bool) {
        open = next_open;
    }

    def handle_query_change(next_query: str) {
        query = next_query;
    }

    def handle_select(current_value: str) {
        value = "" if current_value == value else current_value;
        query = "";
        open = False;
    }

    def handle_create() {
        new_value = trimmed.lower().replace(" ", "-");
        color = label_colors[color_index % len(label_colors)];
        color_index = color_index + 1;
        new_label = LabelEntry(value=new_value, label=trimmed, color=color);
        labels = labels + [new_label];
        value = new_value;
        query = "";
        open = False;
    }

    <div className="w-full max-w-xs">
