import os;

async def getNumberOfFilesInsideDirectory(directoryPath: str) -> int {
    try {
        directoryFullPath: str = os.path.join(os.getcwd(), directoryPath);
        files: list[str] = os.listdir(directoryFullPath);
        fileCount: int = len([
            file for file in files
            if os.path.isfile(os.path.join(directoryFullPath, file))
        ]);
        return fileCount;
    } except Exception as e {
        print(f"error : {str(e)}");
        return 0;
    }
}

async def getFileContent(filePath: str) -> str {
    with open(filePath, encoding="utf8") as fh {
        return fh.read();
    }
}

