"use client";

import { useEffect, useState } from 'react';
import { fetchStoryIds, fetchItemById, StoryType } from './utils/api';
import { relativeTime } from './utils/time';
import Link from 'next/link';
import { Triangle, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';

type Story = {
  id: number;
  title: string;
  url?: string;
  by: string;
  score: number;
  time: number;
  kids?: number[];
};

const SORT_TABS: { key: StoryType; label: string }[] = [
  { key: 'top', label: 'Top' },
  { key: 'new', label: 'New' },
  { key: 'show', label: 'Show' },
  { key: 'ask', label: 'Ask' },
  { key: 'job', label: 'Jobs' },
];

export default function Home() {
  const [stories, setStories] = useState<Story[]>([]);
  const [sortType, setSortType] = useState<StoryType>('top');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(true);
  const storiesPerPage = 10;

  useEffect(() => {
    const getStories = async () => {
      setLoading(true);
      const storyIds = await fetchStoryIds(sortType);
      setTotalPages(Math.ceil(storyIds.length / storiesPerPage));

      const paginatedStoryIds = storyIds.slice(
        (currentPage - 1) * storiesPerPage,
        currentPage * storiesPerPage
      );

      const storiesData = await Promise.all(paginatedStoryIds.map((id: number) => fetchItemById(id)));
      setStories(storiesData.filter((s): s is Story => s && !!s.title));
      setLoading(false);
    };

    getStories();
  }, [currentPage, sortType]);

  const handleNextPage = () => {
    if (currentPage < totalPages) {
      setCurrentPage((prevPage) => prevPage + 1);
    }
  };

  const handleFirstPage = () => {
    setCurrentPage(1);
  }

  const handleLastPage = () => {
    setCurrentPage(totalPages);
  }

  const handlePrevPage = () => {
    if (currentPage > 1) {
      setCurrentPage((prevPage) => prevPage - 1);
    }
  };

  const handleSortChange = (type: StoryType) => {
    if (type === sortType) return;
    setSortType(type);
    setCurrentPage(1);
  };

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'ArrowRight' || event.key === 'L') {
      handleNextPage();
    } else if (event.key === 'ArrowLeft' || event.key === 'H') {
      handlePrevPage();
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [currentPage]);

  useEffect(() => {
    const handleInitialKeyDown = (event: KeyboardEvent) => {
      if (loading) return;
      handleKeyDown(event);
    };

    window.addEventListener('keydown', handleInitialKeyDown);
    return () => {
      window.removeEventListener('keydown', handleInitialKeyDown);
    };
  }, [loading]);

  return (
    <div className="container mx-auto">
      <div className="flex flex-wrap gap-4 px-4 mb-4 text-sm">
        {SORT_TABS.map((tab) => (
          <button
            key={tab.key}
            onClick={() => handleSortChange(tab.key)}
            className={`transition hover:text-orange-400 ${
              sortType === tab.key
                ? 'text-orange-400 underline underline-offset-4'
                : 'text-neutral-400'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="flex justify-center items-center my-4 h-32">
          <p className="text-lg text-neutral-400">Loading...</p>
        </div>
      ) : (
        <>
          <ul className="space-y-6">
            {stories.map((story, j) => (
              <div key={story.id} >
                <li className="hover:bg-neutral-900 shadow-md p-4 transition">
                  <div className="flex flex-col items-start justify-between">

                    <Link
                      href={story.url || `/story/${story.id}`}
                      target="_blank"
                      className="text-lg font-semibold text-white hover:text-orange-400 transition hover:underline"
                    >
                      {story.title}
                    </Link>
                    <p className="text-sm mt-[5px] mb-3 text-neutral-400">
                      by{' '}
                      {story.by ? (
                        <Link href={`/user/${story.by}`} className="text-orange-400 transition hover:text-orange-300 underline">
                          {story.by}
                        </Link>
                      ) : (
                        <span className="text-neutral-500">unknown</span>
                      )}
                    </p>
                    <div>
                      <p className="text-neutral-400 text-sm">
                        <Link
                          href={`/story/${story.id}`}
                          className="text-orange-400 hover:underline cursor-pointer"
                        >
                          {story.kids?.length || 0} comments
                        </Link> <span className="text-neutral-600">|</span>{' '}
                        <Link
                          href={`/story/${story.id}`}
                          className="text-neutral-400 inline-flex items-center gap-[2px] cursor-pointer"
                        >  <Triangle size={13} />
