import from "react" { useState, useEffect, useCallback }

def:pub useArrowVisibility(
    ref: Ref[HTMLElement],
    itemRefs: list[Ref[HTMLElement]],
) -> tuple[bool, bool] {
    left_slot = useState(False);
    leftVisibility = left_slot[0] as bool;
    setLeftVisibility = left_slot[1];
    right_slot = useState(True);
    rightVisibility = right_slot[0] as bool;
    setRightVisibility = right_slot[1];
    computeVisibility = useCallback(lambda -> None {
        if not ref.current {
            return;
        }
        el = ref.current as HTMLElement;
        scrollLeft = el.scrollLeft if el.scrollLeft else 0;
        clientWidth = el.clientWidth if el.clientWidth else 0;
        scrollWidth = el.scrollWidth if el.scrollWidth else 0;
        nextLeft = scrollLeft > 0;
        nextRight = scrollLeft + clientWidth < scrollWidth;
        if leftVisibility != nextLeft {
            setLeftVisibility(nextLeft);
        }
        if rightVisibility != nextRight {
            setRightVisibility(nextRight);
        }
    }, [ref.current, leftVisibility, rightVisibility, setLeftVisibility, setRightVisibility]);
    useEffect(computeVisibility, [itemRefs]);
    useEffect(lambda {
        if not ref.current {
            return;
        }
        el = ref.current as HTMLElement;
        el.addEventListener("resize", computeVisibility);
        el.addEventListener("scroll", computeVisibility);
        return lambda {
            target = ref.current as HTMLElement;
            if target {
                target.removeEventListener("resize", computeVisibility);
                target.removeEventListener("scroll", computeVisibility);
            }
        };
    }, [ref.current, leftVisibility, rightVisibility]);
    return (leftVisibility, rightVisibility);
}
