      label: "Practice in real interview",
      reason: "Strong answer — rehearse it in the real interview setting.",
    };
  }
  if (canNext) {
    return {
      action: "next",
      label: "Next question",
      reason:
        score <= 7
          ? "Apply the feedback below, then keep your momentum going."
          : "Strong answer — keep your momentum going.",
    };
  }
  return {
