      data={data}
      collapsible={collapsible}
      nodeSvgShape={REGULAR_NODE_SVG_STYLE}
      orientation={orientation}
      textLayout={TEXT_LAYOUT}
      transitionDuration={transitionDuration}
      translate={{
        x: dimensions.width / 2,
        y: dimensions.height / 3,
      }}
      onClick={onClick}
      pathFunc={pathFunc}
