async def:pub fetchUsersCamelCase(fetchOptions: FetchParams = FetchParams()) -> object {
    processedSearch = "";
    if fetchOptions.search {
        processedSearch = re.sub(r"\s+", " ", fetchOptions.search.strip());
    }
    query_parts: list[str] = [];
    if processedSearch {
        query_parts.append("search=" + processedSearch);
    }
    if fetchOptions.fromDate {
        query_parts.append("fromDate=" + fetchOptions.fromDate);
    }
    if fetchOptions.toDate {
        query_parts.append("toDate=" + fetchOptions.toDate);
    }
    query_parts.append("sortBy=" + fetchOptions.sortBy);
    query_parts.append("sortOrder=" + fetchOptions.sortOrder);
    query_parts.append("page=" + str(fetchOptions.page));
    query_parts.append("limit=" + str(fetchOptions.limit));
    query = "&".join(query_parts);
    response = await fetch(API_BASE_URL + "/users/camel-case?" + query);
    if not response.ok {
        raise Exception("Failed to fetch users: " + response.statusText);
    }
    data = await response.json();
    return usersCamelCaseResponseSchema.parse(data);
}

