import from "store/tasks/types" { DRAG_AND_DROP, FETCH_TASKS, DELETE_TASK, ITaskState, ITasksDragAndDropAction, ITasksFetchTasksAction, ITasksDeleteTasksAction }

obj DataTransfer {
    def getData(format: str) -> str;
}

type Actions = ITasksDragAndDropAction | ITasksFetchTasksAction | ITasksDeleteTasksAction;

glob initialState: list[ITaskState] = [];

def checkChrome(id: str) -> str {
    if id[0] == "<" {
        import re;
        cleaned = re.sub(r"[^\d]", "", id);
        return cleaned[1:];
    }
    return id;
}

def:pub tasks(
    state: list[ITaskState] = initialState,
    action: Actions
) -> list[ITaskState] {
    switch action["type"] {
        case DRAG_AND_DROP:
            payload = action["payload"] as dict[str, object | str];
            dragEvent = payload["e"] as dict[str, object];
            dataTransfer = dragEvent["dataTransfer"] as DataTransfer;
            htmlId = dataTransfer.getData("text/html");
            checkedId = checkChrome(htmlId);
            for task in state {
                if task["id"] == checkedId {
                    task["type"] = payload["type"] as str;
                }
            }
            return state;
            break;
        case FETCH_TASKS:
            return state + (action["payload"] as list[ITaskState]);
            break;
        case DELETE_TASK:
            return [task for task in state if task["id"] != action["payload"]];
            break;
        default:
            return state;
            break;
    }
}

