import from "react" { useState, useCallback }

def:pub useCommandHistory() -> dict[str, object] {
    _history_state = useState([]);
    history: list[str] = _history_state[0] as list[str];
    setHistory = _history_state[1];
    _index_state = useState(0);
    index: int = _index_state[0] as int;
    setIndex = _index_state[1];

    addToHistory = useCallback(lambda (command: str) {
        setHistory(lambda (prev: list[str]) -> list[str] { return prev + [command]; });
        setIndex(lambda (prev: int) -> int { return prev + 1; });
    }, []);

    getPrevious = useCallback(lambda () -> str {
        if len(history) == 0 {
            return "";
        }
        newIndex = (index - 1) if index > 0 else (len(history) - 1);
        setIndex(newIndex);
        return history[newIndex] or "";
    }, [history, index]);

    getNext = useCallback(lambda () -> str {
        if len(history) == 0 {
            return "";
        }
        newIndex = (index + 1) if index < (len(history) - 1) else 0;
        setIndex(newIndex);
        return history[newIndex] or "";
    }, [history, index]);

    resetIndex = useCallback(lambda () {
        setIndex(len(history) + 1);
    }, [len(history)]);

    return {
        "addToHistory": addToHistory,
        "getPrevious": getPrevious,
        "getNext": getNext,
        "resetIndex": resetIndex
    };
}

