def change_badge_class(change_type: str) -> str {
    if change_type == "feature" {
        return "bg-blue-500/10 text-blue-500 border-blue-500/20";
    } elif change_type == "improvement" {
        return "bg-teal-400/10 text-teal-400 border-teal-400/20";
    } elif change_type == "fix" {
        return "bg-orange-400/10 text-orange-400 border-orange-400/20";
    }
    return "bg-red-500/10 text-red-500 border-red-500/20";
}

def change_badge_label(change_type: str) -> str {
    if change_type == "feature" {
        return "Feature";
    } elif change_type == "improvement" {
        return "Improvement";
    } elif change_type == "fix" {
        return "Fix";
    }
    return "Breaking";
}

def:pub CollapsibleChangelog() -> JsxElement {
    has openVersions: list[str] = ["v3.2.0"];

    def toggle(version: str) {
        if version in openVersions {
            openVersions = [v for v in openVersions if v != version];
        } else {
            openVersions = openVersions + [version];
        }
    }

    <div className="w-full max-w-lg space-y-2">
        {for release in releases {
            <Collapsible
                key={release["version"]}
                open={release["version"] in openVersions}
                onOpenChange={lambda { toggle(release["version"] as str); }}
            >
                <div className="rounded-xl outline bg-background overflow-hidden">
