import from "qianyuanx" { Http }

glob pool: set[Callable[[], None]] = set();
glob waitQueue: list[Callable[[], None]] = [];

def:pub HttpConcurrency(reqFn: str, max: int) -> object {
    return new(Promise, lambda (resolve: Callable[[object], None], reject: Callable[[Exception], None]) {
        isFull = len(pool) >= max;
        def newReqFn() -> None {
            req = Http.get(
                reqFn,
                {"data": {"doctor": "贾梦源", "val1": "请选择", "val2": "请选择", "val3": "请选择", "val4": "请选择", "page": 1, "size": 1}},
            );
            req.then(lambda (res: object) {
                resolve.call(None, res);
            });
            req.catch(lambda (err: Exception) {
                reject.call(None, err);
            });
            req.finally(lambda -> None {
                pool.discard(newReqFn);
                if waitQueue {
                    nextFn = waitQueue.pop(0);
                    pool.add(nextFn);
                    nextFn();
                }
            });
        }
        if isFull {
            waitQueue.append(newReqFn);
        } else {
            pool.add(newReqFn);
            newReqFn();
        }
    });
}

