def:pub CommandSearchDemo(
    buttonLabel: str = "Search files...",
    placeholder: str = "Type a command or search...",
    emptyMessage: str = "No results found.",
    showSeparators: bool = True,
    groups: list[CommandSearchGroup] = defaultGroups,
) -> JsxElement {
    has open: bool = False;

    useEffect(lambda {
        def down(event: KeyboardEvent) {
            if event.key == "j" and (event.metaKey or event.ctrlKey) {
                event.preventDefault();
                open = not open;
            }
        }
        document.addEventListener("keydown", down);
        return lambda { document.removeEventListener("keydown", down); };
    }, []);

  <div className="flex flex-col gap-4">
    <Button onClick={lambda (e: MouseEvent) { open = True; }} variant="outline" className="w-52 cursor-pointer">
      <SearchIcon className="size-4" />
      {buttonLabel}
      <Kbd className="ml-auto">⌘J</Kbd>
    </Button>
    <CommandDialog open={open} onOpenChange={lambda (value: bool) { open = value; }} className="w-full max-w-lg!">
      <Command>
        <CommandInput placeholder={placeholder} />
        <CommandList>
          <CommandEmpty>{emptyMessage}</CommandEmpty>
          {for (index, group) in enumerate(groups) {
            if showSeparators and index > 0 {
              <CommandSeparator key={"sep-" + str(index)} />
            }
            <CommandGroup heading={group.heading} key={group.heading}>
              {for item in group.items {
                <CommandItem
                  key={item.label}
                  className="cursor-pointer"
                  onSelect={item.onSelect}
                >
                  {if item.icon {
                    Icon = item.icon;
                    <Icon className="mr-2 size-4 text-muted-foreground" />
                  }}
                  <span>{item.label}</span>
                  {if item.timestamp {
                    <span className="ml-auto text-xs text-muted-foreground">{item.timestamp}</span>
                  }}
                </CommandItem>
              }}
            </CommandGroup>
          }}
        </CommandList>
        <div className="flex items-center gap-1 border-t p-1">
          <Button variant="ghost" size="icon" className="size-8">
            <Undo2Icon className="size-4" />
          </Button>
          <Button variant="ghost" size="icon" className="size-8">
            <ArrowUpIcon className="size-4" />
          </Button>
          <Button variant="ghost" size="icon" className="size-8">
            <ArrowDownIcon className="size-4" />
          </Button>
        </div>
      </Command>
    </CommandDialog>
  </div>
}
