        attribute="class"
        defaultTheme="system"
        enableSystem
        disableTransitionOnChange={false}
        storageKey="silong-theme"
      >
        <GlobalErrorListeners />
        <ServiceWorkerCleanup />
        <SonnerToaster richColors closeButton />
        {children}
      </ThemeProvider>
    </ChunkErrorBoundary>
  );
}
