import from "lucide-react" { FolderOpenIcon, HardDriveIcon, LoaderCircleIcon, Trash2Icon }
import from "@/components/ui/button" { Button }
import from "@/components/ui/select" { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue }
import from "@/lib/format" { formatBytes }
import from "@/stores/settings-store" { READER_CACHE_LIMITS_MB }
import from "./shared.jac" { SettingRow, SettingsSection }

def formatCacheLimit(limitMb: float) -> str {
    return f"{(limitMb / 1024)} GB" if limitMb >= 1024 else f"{limitMb} MB";
}

def CacheSize(stats: dict[str, object]) -> JsxElement {
    if stats["isLoading"] {
        return <LoaderCircleIcon className="size-4 animate-spin" />;
    }
    data = stats["data"];
    if data {
        return <span>{formatBytes((data as dict[str, object])["totalBytes"] as float)}</span>;
    }
    return <span>—</span>;
}

def:pub CacheSection(
    readerCacheLimitMb: int,
    stats: dict[str, object],
    isOpeningCacheDir: bool,
    isClearingCache: bool,
    onCacheLimitChange: Callable[[int], None],
    onOpenCacheDir: Callable[[], None],
    onClearCache: Callable[[], None]
) -> JsxElement {
    def handle_limit_change(value: str) {
        onCacheLimitChange(int(value));
    }
    def handle_open_dir() {
        onOpenCacheDir();
    }
    def handle_clear() {
        onClearCache();
    }
    return <SettingsSection icon={<HardDriveIcon className="size-4" />} title="缓存">
        <SettingRow title="当前缓存大小" description="已解码图片当前占用的磁盘空间">
            <CacheSize stats={stats} />
        </SettingRow>
        <SettingRow title="缓存大小设置" description="超过上限后会自动清理较旧的图片缓存">
            <Select value={str(readerCacheLimitMb)} onValueChange={handle_limit_change}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                    <SelectGroup>
                        {[<SelectItem key={str(limitMb)} value={str(limitMb)}>{formatCacheLimit(limitMb as float)}</SelectItem> for limitMb in READER_CACHE_LIMITS_MB]}
                    </SelectGroup>
                </SelectContent>
            </Select>
        </SettingRow>
        <SettingRow title="缓存目录" description="打开本地图片缓存所在文件夹">
            <Button variant="outline" onClick={handle_open_dir} disabled={isOpeningCacheDir}>
                <FolderOpenIcon className="size-4" />
                {"打开目录"}
            </Button>
        </SettingRow>
        <SettingRow title="清空缓存" description="删除所有已缓存的阅读图片">
            <Button variant="destructive" onClick={handle_clear} disabled={isClearingCache}>
                <Trash2Icon className="size-4" />
                {"清空缓存"}
            </Button>
        </SettingRow>
    </SettingsSection>;
}

