    const timeout = window.setTimeout(() => setStatus("idle"), 2000);
    return () => window.clearTimeout(timeout);
  }, [status]);

  const handleCopy = React.useCallback(() => {
    writeClipboardText(command).then(
      () => setStatus("copied"),
      () => setStatus("failed"),
    );
  }, [command]);

  return (
