        position = {"x": float(e.clientX), "y": float(e.clientY)};
        isVisible = True;
    }

    def hide_menu() {
        isVisible = False;
    }

  <>
    <div
      onContextMenu={handle_context_menu}
      onClick={hide_menu}
      className={cn(
