        <>
          <div className="fixed inset-0 z-40" onClick={hide_menu} />
          <motion.div
            initial={{"opacity": 0, "scale": 0.95}}
            animate={{"opacity": 1, "scale": 1}}
            exit={{"opacity": 0, "scale": 0.95}}
            transition={{"duration": 0.15}}
            className="fixed z-50 w-52 overflow-hidden rounded-2xl border border-border/80 bg-background p-1.5"
            style={{"left": position["x"], "top": position["y"]}}
          >
            {for (index, item) in enumerate(items) {
              if item.danger {
                <Separator className="my-1.5" key={"sep-" + item.label} />
              }
              Icon = item.icon;
              def handle_item_click(e: MouseEvent) {
                if item.onClick {
                  item.onClick();
                }
                isVisible = False;
              }
              <motion.button
                key={item.label}
                initial={{"opacity": 0, "x": -10}}
                animate={{"opacity": 1, "x": 0}}
                transition={{"delay": float(index) * 0.05}}
                className={cn(
                  "flex w-full cursor-pointer items-center justify-between rounded-xl px-2.5 py-2 text-left text-sm font-medium transition-colors",
                  "text-red-500 hover:bg-red-500/10" if item.danger else "text-foreground hover:bg-muted dark:hover:bg-muted/50",
                )}
                onClick={handle_item_click}
              >
                <div className="flex items-center gap-2.5">
                  <div className={cn("flex h-7 w-7 items-center justify-center rounded-lg", item.iconBg)}>
                    <Icon className={cn("h-3.5 w-3.5", item.iconColor)} />
                  </div>
                  <span>{item.label}</span>
                </div>
                <span className="text-xs text-muted-foreground">{item.shortcut}</span>
              </motion.button>
            }}
          </motion.div>
        </>
      }}
    </AnimatePresence>
  </>
}

