import re;
import from datetime { datetime }
import from "clsx" { clsx }
import from "tailwind-merge" { twMerge }

type ClassValue = str | bool | None | dict[str, bool | str | None] | list[str | bool | None | dict[str, bool | str | None]];

def:pub cn(*inputs: ClassValue) -> str {
    return twMerge(clsx(inputs));
