def capitalize_word(word: str) -> str {
    if len(word) == 0 {
        return word;
    }
    return word[0].upper() + word[1:];
}

def:pub formatSlug(slug: str) -> str {
    return " ".join([capitalize_word(word) for word in slug.split("-")]);
}

def:pub generateId(text: str) -> str {
    step1 = re.sub(r"[^\w\s-]", "", text.lower());
    return re.sub(r"\s+", "-", step1);
}

def:pub slugify(text: str) -> str {
    step1 = re.sub(r"[^\w\s-]", "", text.lower());
    step2 = re.sub(r"\s+", "-", step1);
    return re.sub(r"^-+|-+$", "", step2);
}

def:pub formatDate(date: str) -> str {
    dt = datetime.fromisoformat(date.replace("Z", "+00:00"));
    return dt.strftime("%B %d, %Y");
}

