import from "lucide-react" { GlobeCheckIcon }
import from "@/components/ui/input" { Input }
import from "@/components/ui/select" { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue }
import from "@/stores/settings-store" { PROXY_MODES }
import from "./shared.jac" { SettingRow, SettingsSection }

def formatProxyMode(mode: str) -> str {
    if mode == "http" {
        return "HTTP";
    }
    if mode == "socks5" {
        return "SOCKS5";
    }
    return "关闭";
}

def:pub ProxySection(
    proxyMode: str,
    proxyHost: str,
    proxyPort: int,
    onProxyModeChange: Callable[[str], None],
    onProxyHostChange: Callable[[str], None],
    onProxyPortChange: Callable[[int], None]
) -> JsxElement {
    def handle_host_change(e: ChangeEvent) {
        onProxyHostChange(e.target.value);
    }
    def handle_port_change(e: ChangeEvent) {
        onProxyPortChange(int(e.target.value));
    }
    return <SettingsSection icon={<GlobeCheckIcon className="size-4" />} title="代理">
        <SettingRow title="本地代理" description="为接口和阅读图片请求启用本机 HTTP 或 SOCKS5 代理">
            <div className="flex items-center gap-2">
                <Select value={proxyMode} onValueChange={onProxyModeChange}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                        <SelectGroup>
                            {[<SelectItem key={mode as str} value={mode as str}>{formatProxyMode(mode as str)}</SelectItem> for mode in PROXY_MODES]}
                        </SelectGroup>
                    </SelectContent>
                </Select>
                <Input value={proxyHost} disabled={proxyMode == "off"} onChange={handle_host_change} />
                <Input value={str(proxyPort)} disabled={proxyMode == "off"} onChange={handle_port_change} />
            </div>
        </SettingRow>
    </SettingsSection>;
}

