    () => new ConvexReactClient(process.env.NEXT_PUBLIC_CONVEX_URL as string),
  );
  return (
    <ConvexProvider client={convex}>
      <FilesProvider>{children}</FilesProvider>
    </ConvexProvider>
  );
}
