import re;
import from "@/components/blocks/code-viewer/blocks-screen-width" { BLOCK_SCREENSHOT_EXTENSION }

obj BlockFile {
    has path: str;
    has target: str | None = None;
}

def setNestedObject(currentTree: list[dict[str, object]], isFile: bool, path: str, target: str) {
    parts = (target or path).split("/");
    current = currentTree;
    for (index, part) in enumerate(parts) {
        if index == len(parts) - 1 {
            if isFile {
                current.append({"name": part, "type": "file", "path": path, "target": target});
            }
        } else {
            existingFolder: dict[str, object] | None = None;
            for item in current {
                if item.get("name") == part {
                    existingFolder = item;
                    break;
                }
            }
            if existingFolder is None {
                existingFolder = {"name": part, "type": "folder", "children": []};
                current.append(existingFolder);
            }
            children = existingFolder.get("children");
            if children is not None and isinstance(children, list) {
                current = children as list[dict[str, object]];
            }
        }
    }
}

def:pub getFileTree(files: list[BlockFile]) -> list[dict[str, object]] {
    fileTree: list[dict[str, object]] = [];
    for file in files {
        source = re.sub("^@/blocks/", "", file.path);
        setNestedObject(fileTree, True, source, file.target or "");
    }
    return fileTree;
}

def:pub removeBlockPrefixFromPath(path: str) -> str {
    return re.sub("^@/blocks/", "", path);
}

def:pub getBlockScreenshot(blockName: str) -> str {
    return f"/images/blocks/screenshots/{blockName}.{BLOCK_SCREENSHOT_EXTENSION}";
}

