        user = None;
    }
    if user is None {
        try {
            headerStore = await headers();
            authorization = headerStore.get("authorization");
            if authorization and authorization.startswith("Bearer ") {
                token = authorization[7:];
                bearerResult = await serverClient.auth.getUser(token);
                user = bearerResult.data.user;
            }
        } except Exception {
            user = None;
        }
    }
    return {"user": user, "supabase": supabaseAdmin};
}

