        featured = skill["featured"] as bool;
        agentSkillRoutes = agentSkillRoutes + [{"url": str(URL(detailHref, baseUrl)), "changeFrequency": "weekly", "priority": 0.7 if featured else 0.6}];
    }
    return staticRoutes + agentSkillRoutes;
}

