 */
export const DEFAULT_LAYOUTS: Record<string, ModuleLayout> = Object.fromEntries(
  Object.values(definitions).map((def) => [def.id, def.defaultLayout]),
);

/** 模板是否支持双栏布局（sidebar 非空即为双栏） */
