export function getEffectiveLayout(
  template: string,
  moduleLayout?: Record<string, ModuleLayout>,
): ModuleLayout {
  const custom = moduleLayout?.[template];
  if (custom) return custom;
  return DEFAULT_LAYOUTS[template] ?? defaultDefinition.defaultLayout;
}

