                components={{"Dropdown": CalendarDropdown, "DropdownNav": CalendarDropdownNav}}
                defaultMonth={new(Date)}
                hideNavigation={True}
                mode="single"
                onSelect={lambda (v: Date | None) { date = v; }}
                selected={date}
                startMonth={new(Date, 1980, 6)}
