import from "react" { Children, isValidElement }

glob variants: dict[str, str] = {
    "primary": "bg-brand-violet hover:bg-brand-violet-light text-brand-white",
    "secondary": "bg-brand-violet-ghost hover:bg-brand-violet-highlight text-brand-violet-muted",
    "tertiary": "bg-brand-gray hover:bg-brand-text text-brand-text-muted",
    "delete": "bg-brand-red hover:bg-brand-red-light text-brand-white",
};

def map_button_child(child: object) -> JsxElement {
    if isValidElement(child) {
        return child as JsxElement;
    }
    return <span className="mt-[9px] mb-2 mx-4">{child}</span>;
}

def:pub Button(onClick: Callable[[MouseEvent], None], variant: str = "primary", children: object | None = None, widthFull: bool = False) -> JsxElement {
    variant_class = variants[variant];
    width_class = "w-full justify-center" if widthFull else "";
    class_name = f"text-sm rounded-3xl flex items-center py-2 px-2 h-12 {variant_class} {width_class}";

    def handle_click(e: MouseEvent) {
        onClick(e);
    }

    return <button onClick={handle_click} className={class_name}>{[map_button_child(child) for child in Children.toArray(children)]}</button>;
}

