import from "@/app/api/prep/_lib" { resolveOrgIdFromInterview, trimForPrompt, userCanAccessPrepInterview }
import from "@/lib/supabase/admin" { supabaseAdmin }

glob CACHE_TTL_MS = 5 * 60 * 1000;

glob interviewContextCache: dict[str, dict] = {};

async def:pub getCachedPrepInterviewContext(interviewId: str, userId: str) -> dict {
    cached = interviewContextCache.get(interviewId);
    if cached and cached["expiresAt"] > Date.now() and cached["interview"]["userId"] == userId {
        return {
            "interview": cached["interview"],
            "orgId": cached["orgId"],
            "trimmedJobDescription": cached["trimmedJobDescription"],
            "trimmedResumeText": cached["trimmedResumeText"],
        };
    }
    response = await supabaseAdmin.from("interviews").select('id, "userId", "projectId", language, "followUpDepth", "jobDescription", "resumeText", "companyName", "roleTitle", title').eq("id", interviewId).single();
    interview = response.data;
    if not interview {
        return {"error": "not_found"};
    }
    typedInterview = interview as dict;
    canAccess = await userCanAccessPrepInterview(typedInterview, userId);
    if not canAccess {
        return {"error": "not_found"};
    }
    orgId = await resolveOrgIdFromInterview(typedInterview);
    trimmedJobDescription = trimForPrompt(typedInterview.get("jobDescription", ""));
    trimmedResumeText = trimForPrompt(typedInterview.get("resumeText", ""));
    result = {
        "interview": typedInterview,
        "orgId": orgId,
        "trimmedJobDescription": trimmedJobDescription,
        "trimmedResumeText": trimmedResumeText,
    };
    interviewContextCache[interviewId] = {**result, "expiresAt": Date.now() + CACHE_TTL_MS};
    return result;
}

