def:pub resolveTokensColor(tokens: int) -> Literal["mint", "amber", "tomato"] {
    if not tokens {
        return "tomato";
    }
    tokensColor: Literal["mint", "amber", "tomato"] = "mint";
    if tokens < 10 {
        tokensColor = "amber";
    }
    if tokens < 5 {
        tokensColor = "tomato";
    }
    return tokensColor;
}

