async def:pub getStaticProps() -> dict[str, object] {
    response = await getUserRepositories(author.github);
    data: list[dict[str, object]] = response.data as list[dict[str, object]];
    filtered = [project for project in data if github_repo_visible(project)];
    sorted_projects = sorted(filtered, key=github_repo_stars, reverse=True);
    repos: list[dict[str, str | int]] = [{"fork_count": project["forks_count"] as int, "name": project["name"] as str, "star": project["stargazers_count"] as int, "lang": project["language"] as str, "desc": (project["description"] as str) if project["description"] else "No Description Provided", "link": project["html_url"] as str} for project in sorted_projects[0:12]];
