 */
export function ColumnControls<T>({
  table,
  density,
  onDensityChange,
}: ColumnControlsProps<T>) {
  const hideableColumns = table
    .getAllLeafColumns()
    .filter((column) => column.getCanHide());

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button type="button" variant="outline" size="sm">
            <SlidersHorizontalIcon data-icon="inline-start" />
            Columns
