                  <Label key={column.id} htmlFor={id} className="gap-2">
                    <Checkbox
                      id={id}
                      checked={column.getIsVisible()}
                      onCheckedChange={(checked) =>
                        column.toggleVisibility(checked === true)
                      }
                    />
                    {columnLabel(column)}
