obj Ripple {
    has id: int;
    has x: float;
    has y: float;
}

def:pub RippleButton(
    children: str | JsxElement | None = None,
    onClick: Callable[[MouseEvent], None] | None = None,
    className: str = "",
    variant: str = "default",
    size: str = "default",
    scale: float = 10.0,
    transition: dict[str, float | str] = {"duration": 0.6, "ease": "easeOut"},
) -> JsxElement {
    has ripples: list[Ripple] = [];

    def create_ripple(event: MouseEvent) {
        rect = event.currentTarget.getBoundingClientRect();
        x = event.clientX - rect.left;
        y = event.clientY - rect.top;
        new_ripple = Ripple(id=int(Date.now()), x=x, y=y);
        ripples = ripples + [new_ripple];
        setTimeout(lambda {
            ripples = [r for r in ripples if r.id != new_ripple.id];
        }, 600);
    }

    def handle_click(event: MouseEvent) {
        create_ripple(event);
        if onClick {
            onClick(event);
        }
    }

    <motion.button
        data-slot="button"
        onClick={handle_click}
        className={cn(
            buttonVariants({"variant": variant, "size": size}),
            "relative overflow-hidden",
            "active:translate-y-0",
            className
        )}
    >
        {children}
        {for ripple in ripples {
            <motion.span
                key={str(ripple.id)}
                initial={{"scale": 0, "opacity": 0.5}}
                animate={{"scale": scale, "opacity": 0}}
                transition={transition}
                className="pointer-events-none absolute size-5 rounded-full bg-current"
