def:pub validateSearchInput(keyword: str) -> dict[str, str] {
    error = {"keyword": ""};
    fullNameRegex = re.compile(r"^[A-Za-z0-9가-힣ㄱ-ㅎㅏ-ㅣ]{1,8}$");
    if re.search(r"[\s]", keyword) {
        error["keyword"] = ERROR_MESSAGE_NO_BLANK;
    } elif not fullNameRegex.match(keyword) {
        error["keyword"] = ERROR_MESSAGE_ONLY_KO_EN_NUM;
    }
    return error;
}

