  filters: EMPTY_GEO_LOG_FILTERS,
  setFilters: () => {},
})

export function GeoLogFiltersProvider({
  filters,
  setFilters,
  children,
}: GeoLogFiltersValue & { children: React.ReactNode }) {
  return (
