  if (!isConfigured()) {
    return null;
  }

  const res = await fetch(
    `${VERCEL_API}/v6/domains/${domain}/config${getTeamParam()}`,
    {
      method: 'GET',
      headers: getHeaders(),
    }
  );

  if (!res.ok) {
    return null;
  }

  return (await res.json()) as {
    configuredBy: string | null;
    misconfigured: boolean;
  };
}

