import from datetime { datetime, timedelta }

glob MS_PER_DAY = 86400000;

def:pub buildDailyRange(fromDate: str, toDate: str) -> list[str] {
    start = datetime.fromisoformat(fromDate);
    end = datetime.fromisoformat(toDate);
    if (end < start) {
        return [];
    }
    days = (end - start).days;
    return [(start + timedelta(days=i)).date().isoformat() for i in range(days + 1)];
}

