import re;
import from "@/lib/supabase/admin" { supabaseAdmin }

glob DEFAULT_SIGNED_URL_TTL_SECONDS = ((60 * 60) * 24);

async def:pub resolveStorageSignedUrl(
    bucket: str,
    path: str,
    expiresInSeconds: int = DEFAULT_SIGNED_URL_TTL_SECONDS,
) -> str | None {
    signed = await supabaseAdmin.storage.from(bucket).createSignedUrl(path, expiresInSeconds);
    error = signed.error;
    data = signed.data;
    if error or data is None {
        return None;
    }
    signedUrl = data.signedUrl;
    if not signedUrl {
        return None;
    }
    return signedUrl;
}

async def:pub resolveRecordingSignedUrl(
    stored: str,
    bucket: str = "recordings",
) -> str | None {
    pathMatch = re.match(r"\/recordings\/(.+?)(?:\?|$)", stored);
    path = pathMatch.group(1) if pathMatch else stored;
    return await resolveStorageSignedUrl(bucket, path);
}

